
function asCaptureStateId(value) {
  if (value === "requestingcamera") return "requestingcamera";
  if (value === "idle") return "idle";
  if (value === "camera-ready") return "camera-ready";
  if (value === "capturing") return "capturing";
  if (value === "error") return "error";
  return "idle";
}

export function renderProviderStatus({ providerId, active, message = "pronto", registry, requestedProviderId, captureState }) {
  const resolvedId = registry ? registry.resolveSelection(providerId) : providerId;

  const effectiveRequestedId = requestedProviderId ?? providerId;

  const resolvedLabel = (() => {
    if (registry && effectiveRequestedId === "auto") {
      if (resolvedId === "unknown") {
        return "nenhum backend disponível";
      }
      const metadata = registry.getMetadata(resolvedId);
      if (metadata) {
        return metadata.label;
      }
      return resolvedId;
    }
    if (resolvedId === "unknown") {
      return "nenhum backend disponível";
    }
    return resolvedId;
  })();

  const reason = (() => {
    if (!registry) return undefined;
    const targetId = requestedProviderId ?? providerId;
    const metadata = registry.getMetadata(targetId);
    return metadata?.reasonUnavailable;
  })();

  const requestingCamera = asCaptureStateId(captureState) === "requestingcamera";
  const isCapturing = asCaptureStateId(captureState) === "capturing";
  const isCameraReady = asCaptureStateId(captureState) === "camera-ready";

  const backendPillColor =
    requestingCamera
      ? { background: "#2a3a2e", color: "#cfe9d4" }
      : isCapturing && active
        ? { background: "#1c3a2e", color: "#7fe3b4" }
        : { background: "#2a2a33", color: "#b9b9c4" };

  const messagePillColor =
    requestingCamera || isCapturing
      ? { background: "#2a3a2e", color: "#cfe9d4" }
      : { background: "#2a2a33", color: "#b9b9c4" };

  const messageToRender =
    requestingCamera
      ? "solicitando câmera…"
      : isCapturing && active
        ? message || "capturando…"
        : isCameraReady && active
          ? message || "câmera pronta"
          : active
            ? message
            : "pendente";

  const row = document.createElement("div");
  row.className = "mf-provider-status-row";
  row.style.display = "flex";
  row.style.alignItems = "center";
  row.style.gap = "8px";
  row.style.padding = "6px 0";

  const label = document.createElement("span");
  label.className = "mf-provider-status-label";
  label.style.fontSize = "12px";
  label.style.color = "#b9b9c4";
  label.style.textTransform = "uppercase";
  label.style.letterSpacing = "0.5px";
  label.textContent = "Backend ativo";

  const backendValue = document.createElement("span");
  backendValue.className = "mf-provider-status-value";
  backendValue.style.fontSize = "12px";
  backendValue.style.color = backendPillColor.color;
  backendValue.style.background = backendPillColor.background;
  backendValue.style.padding = "4px 8px";
  backendValue.style.borderRadius = "6px";
  backendValue.textContent = resolvedLabel;

  const messageValue = document.createElement("span");
  messageValue.className = "mf-provider-status-value";
  messageValue.style.fontSize = "12px";
  messageValue.style.color = messagePillColor.color;
  messageValue.style.background = messagePillColor.background;
  messageValue.style.padding = "4px 8px";
  messageValue.style.borderRadius = "6px";
  messageValue.textContent = messageToRender;

  row.appendChild(label);
  row.appendChild(backendValue);
  row.appendChild(messageValue);

  if (reason) {
    const reasonEl = document.createElement("span");
    reasonEl.className = "mf-provider-status-reason";
    reasonEl.style.fontSize = "11px";
    reasonEl.style.color = "#f0888a";
    reasonEl.style.marginLeft = "auto";
    reasonEl.textContent = reason;
    row.appendChild(reasonEl);
  }

  return row;
}
